import (
	"context"
	_ "embed"
	"fmt"
	"os"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
	"go.mongodb.org/mongo-driver/mongo/readpref"
)

//go:embed migrations/001_schema.sql
var schemaSQL string

// DB holds the active datastore connections.
type DB struct {
	PG    *pgxpool.Pool
	Mongo *mongo.Client
	DbName string
}

// PostgresURL returns the configured Postgres DSN, falling back to the env var.
func PostgresURL() string {
	if v := os.Getenv("DATABASE_URL"); v != "" {
		return v
	}
	return "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
}

// MongoURL returns the configured MongoDB URI.
func MongoURL() string {
	if v := os.Getenv("MONGODB_URI"); v != "" {
		return v
	}
	return "mongodb://127.0.0.1:27017/arena"
}

func dbName(uri string) string {
	const marker = "arena"
	return marker
}

// Connect opens both datastore connections, retrying until they are reachable.
func Connect(ctx context.Context) (*DB, error) {
	pgpool, err := connectPG(ctx)
	if err != nil {
		return nil, err
	}
	mc, err := connectMongo(ctx)
	if err != nil {
		pgpool.Close()
		return nil, err
	}
	return &DB{PG: pgpool, Mongo: mc, DbName: "arena"}, nil
}

func connectPG(ctx context.Context) (*pgxpool.Pool, error) {
	cfg, err := pgxpool.ParseConfig(PostgresURL())
	if err != nil {
		return nil, fmt.Errorf("parse pg url: %w", err)
	}
	cfg.MaxConns = 10
	cfg.MinConns = 1
	cfg.MaxConnLifetime = 30 * time.Minute
	var pool *pgxpool.Pool
	for i := 0; i < 60; i++ {
		pool, err = pgxpool.NewWithConfig(ctx, cfg)
		if err == nil {
			err = pool.Ping(ctx)
		}
		if err == nil {
			return pool, nil
		}
		if pool != nil {
			pool.Close()
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(1 * time.Second):
		}
	}
	return nil, fmt.Errorf("postgres not reachable: %w", err)
}

func connectMongo(ctx context.Context) (*mongo.Client, error) {
	uri := MongoURL()
	var mc *mongo.Client
	var err error
	for i := 0; i < 60; i++ {
		mc, err = mongo.Connect(ctx, options.Client().ApplyURI(uri))
		if err == nil {
			err = mc.Ping(ctx, readpref.Primary())
		}
		if err == nil {
			return mc, nil
		}
		if mc != nil {
			_ = mc.Disconnect(ctx)
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(1 * time.Second):
		}
	}
	return nil, fmt.Errorf("mongo not reachable: %w", err)
}

// Migrate applies the embedded schema. Safe to run repeatedly.
func Migrate(ctx context.Context, pg *pgxpool.Pool) error {
	_, err := pg.Exec(ctx, schemaSQL)
	return err
}

// Ping verifies both datastores are reachable.
func (d *DB) Ping(ctx context.Context) error {
	if err := d.PG.Ping(ctx); err != nil {
		return fmt.Errorf("pg: %w", err)
	}
	if err := d.Mongo.Ping(ctx, readpref.Primary()); err != nil {
		return fmt.Errorf("mongo: %w", err)
	}
	return nil
}","path":"/workspace/backend/internal/db/db.go"}

{"command":"create","file_text":"package db

import (
	"context"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.mongodb.org/mongo-driver/mongo"
)

// ResetSchema fully materializes a clean application state: it recreates the
// Postgres schema and Mongo collections/indexes. Safe to run repeatedly; the
// application must be stopped when called.
func ResetSchema(ctx context.Context, pg *pgxpool.Pool, mc *mongo.Client, dbName string) error {
	// Drop all application tables in dependency order, then recreate.
	drop := []string{
		"checkpoints", "handoffs", "assignment_progress", "capacity_reservations",
		"stops", "assignments", "journeys", "samples", "requests",
		"disruptions", "serviceability_snapshots", "idempotency",
		"laboratory_acceptance", "capacity", "connections", "locations",
		"sample_types", "certifications", "qualifications", "user_roles",
		"sessions", "users",
	}
	for _, t := range drop {
		if _, err := pg.Exec(ctx, "DROP TABLE IF EXISTS "+t+" CASCADE"); err != nil {
			return err
		}
	}
	if err := Migrate(ctx, pg); err != nil {
		return err
	}
	if err := resetMongo(ctx, mc, dbName); err != nil {
		return err
	}
	return nil
}

func resetMongo(ctx context.Context, mc *mongo.Client, dbName string) error {
	db := mc.Database(dbName)
	// Materialize collections explicitly (Mongo would otherwise create them lazily).
	for _, name := range MongoCollections {
		if err := db.CreateCollection(ctx, name); err != nil {
			// Already exists: drop and recreate to guarantee clean state.
			if err2 := db.Collection(name).Drop(ctx); err2 != nil {
				return err2
			}
			if err2 := db.CreateCollection(ctx, name); err2 != nil {
				return err2
			}
		}
	}
	// Indexes.
	if err := ensureMongoIndexes(ctx, db); err != nil {
		return err
	}
	return nil
}

// MongoCollections is the full set of Mongo collections the app uses.
var MongoCollections = []string{
	"audit_log",
	"realtime_events",
}

func ensureMongoIndexes(ctx context.Context, db *mongo.Database) error {
	_, err := db.Collection("audit_log").Indexes().CreateMany(ctx, []mongo.Index{
		{Keys: map[string]any{"entityType": 1, "entityId": 1}},
		{Keys: map[string]any{"actorId": 1}},
		{Keys: map[string]any{"action": 1}},
		{Keys: map[string]any{"role": 1}},
		{Keys: map[string]any{"at": -1}},
	})
	if err != nil {
		return err
	}
	_, err = db.Collection("realtime_events").Indexes().CreateMany(ctx, []mongo.Index{
		{Keys: map[string]any{"seq": 1}},
		{Keys: map[string]any{"sampleId": 1}},
	})
	return err
}","path":"/workspace/backend/internal/db/reset.go"}

