func (s *Store) LocationByID(ctx context.Context, id uuid.UUID) (*Location, error) {
	row := s.PG.QueryRow(ctx, `SELECT location_id, name, lat, lon, coverage_km, handling_minutes, active,
		fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations WHERE location_id=$1`, id)
	return scanLocation(row)
}

func (s *Store) AllLocations(ctx context.Context) ([]*Location, error) {
	rows, err := s.PG.Query(ctx, `SELECT location_id, name, lat, lon, coverage_km, handling_minutes, active,
		fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations ORDER BY name`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Location
	for rows.Next() {
		l, err := scanLocation(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, l)
	}
	return out, nil
}

func scanLocation(r pgx.Row) (*Location, error) {
	var l Location
	if err := r.Scan(&l.LocationID, &l.Name, &l.Lat, &l.Lon, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
		&l.Functions.CollectionPoint, &l.Functions.TransferPoint, &l.Functions.Hub, &l.Functions.Laboratory); err != nil {
		return nil, err
	}
	return &l, nil
}

func (s *Store) SetLocationStatus(ctx context.Context, tx pgx.Tx, id uuid.UUID, active bool) error {
	_, err := tx.Exec(ctx, "UPDATE locations SET active=$2 WHERE location_id=$1", id, active)
	return err
}

func (s *Store) SetLocationFunctionStatus(ctx context.Context, tx pgx.Tx, id uuid.UUID, fn string, active bool) (LocationFunction, error) {
	col := ""
	switch fn {
	case "collection_point":
		col = "fn_collection_point"
	case "transfer_point":
		col = "fn_transfer_point"
	case "hub":
		col = "fn_hub"
	case "laboratory":
		col = "fn_laboratory"
	}
	if col == "" {
		return LocationFunction{}, ErrInvalid
	}
	_, err := tx.Exec(ctx, "UPDATE locations SET "+col+"=$2 WHERE location_id=$1", id, active)
	if err != nil {
		return LocationFunction{}, err
	}
	var fns LocationFunction
	row := tx.QueryRow(ctx, "SELECT fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations WHERE location_id=$1", id)
	if err := row.Scan(&fns.CollectionPoint, &fns.TransferPoint, &fns.Hub, &fns.Laboratory); err != nil {
		return LocationFunction{}, err
	}
	return fns, nil
}

