{"command":"create","file_text":"package serviceability

import (
	"context"
	"sort"
	"sync"
	"time"

	"github.com/google/uuid"
	"github.com/labsample/app/internal/geo"
	"github.com/labsample/app/internal/store"
)

// Engine plans routes and computes serviceability over the network structure.
type Engine struct {
	store *store.Store
	mu    sync.Mutex
}

func New(s *store.Store) *Engine {
	return &Engine{store: s}
}

// RouteResult describes a planned route from origin to a laboratory.
type RouteResult struct {
	Serviceable       bool
	Reason            string
	TargetLabID       uuid.UUID
	EstimatedArrival  time.Time
	RouteLocations    []uuid.UUID // ordered, including collection point and lab
	TotalTravelMinutes int
	TotalCost         float64
	Cooled            bool
}

// PlanRoute finds a route from the origin coordinate to an accepting lab.
// If originNode is provided (clinic/node), the route starts there.
func (e *Engine) PlanRoute(ctx context.Context, originLat, originLon float64, originNode *uuid.UUID, sampleTypeID uuid.UUID, requiresCooled bool, earliest time.Time, deadline time.Time) (RouteResult, error) {
	locs, err := e.store.AllLocations(ctx)
	if err != nil {
		return RouteResult{Serviceable: false, Reason: "network unavailable"}, err
	}
	conns, err := e.store.AllConnections(ctx)
	if err != nil {
		return RouteResult{Serviceable: false, Reason: "network unavailable"}, err
	}
	acceptingLabs, err := e.store.AcceptingLabs(ctx, sampleTypeID)
	if err != nil {
		return RouteResult{Serviceable: false, Reason: "network unavailable"}, err
	}
	labSet := map[uuid.UUID]bool{}
	for _, l := range acceptingLabs {
		labSet[l] = true
	}

	locByID := map[uuid.UUID]*store.Location{}
	activeCollPoints := []*store.Location{}
	for _, l := range locs {
		locByID[l.LocationID] = l
		if l.Active && l.Functions.CollectionPoint {
			activeCollPoints = append(activeCollPoints, l)
		}
	}

	// Determine start node(s).
	var starts []uuid.UUID
	if originNode != nil {
		if l, ok := locByID[*originNode]; ok && l.Active {
			starts = []uuid.UUID{*originNode}
		}
	} else {
		// Find collection points within coverage of origin.
		for _, l := range activeCollPoints {
			if geo.HaversineKm(originLat, originLon, l.Lat, l.Lon) <= l.CoverageKm {
				starts = append(starts, l.LocationID)
			}
		}
	}
	if len(starts) == 0 {
		return RouteResult{Serviceable: false, Reason: "origin not within 5km of an active collection node"}, nil
	}

	// Build adjacency over active connections (respecting cooled requirement for Frost).
	type edge struct {
		to     uuid.UUID
		mins   int
		cost   float64
		cooled bool
	}
	adj := map[uuid.UUID][]edge{}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if requiresCooled && !c.Cooled {
			continue
		}
		adj[c.FromLocation] = append(adj[c.FromLocation], edge{c.ToLocation, c.TravelMinutes, c.CostUnits, c.Cooled})
	}

	// Dijkstra over earliest arrival time from each start, choosing the best lab.
	// Start time = earliest collection time.
	bestArrival := map[uuid.UUID]time.Time{}
	bestCost := map[uuid.UUID]float64{}
	bestPath := map[uuid.UUID][]uuid.UUID{}
	type node struct {
		loc   uuid.UUID
		arriv time.Time
		cost  float64
		path  []uuid.UUID
	}
	var pq []node
	for _, s := range starts {
		if l := locByID[s]; l != nil {
			startArrival := earliest.Add(time.Duration(l.HandlingMinutes) * time.Minute)
			bestArrival[s] = startArrival
			bestCost[s] = 0
			bestPath[s] = []uuid.UUID{s}
			pq = append(pq, node{s, startArrival, 0, []uuid.UUID{s}})
		}
	}

	for len(pq) > 0 {
		sort.Slice(pq, func(i, j int) bool { return pq[i].arriv.Before(pq[j].arriv) })
		cur := pq[0]
		pq = pq[1:]
		if cur.arriv.After(bestArrival[cur.loc]) && !cur.arriv.Equal(bestArrival[cur.loc]) {
			continue
		}
		for _, e := range adj[cur.loc] {
			l := locByID[e.to]
			arriv := cur.arriv.Add(time.Duration(e.mins)*time.Minute + time.Duration(l.HandlingMinutes)*time.Minute)
			if prev, ok := bestArrival[e.to]; !ok || arriv.Before(prev) {
				bestArrival[e.to] = arriv
				bestCost[e.to] = cur.cost + e.cost
				np := append([]uuid.UUID{}, cur.path...)
				np = append(np, e.to)
				bestPath[e.to] = np
				pq = append(pq, node{e.to, arriv, cur.cost + e.cost, np})
			}
		}
	}

	// Pick best accepting lab by earliest arrival that meets deadline.
	var bestLab uuid.UUID
	var bestArr time.Time
	var bestLabCost float64
	var bestLabPath []uuid.UUID
	found := false
	for l, arr := range bestArrival {
		if labSet[l] && locByID[l].Functions.Laboratory {
			if !found || arr.Before(bestArr) {
				bestLab = l
				bestArr = arr
				bestLabCost = bestCost[l]
				bestLabPath = bestPath[l]
				found = true
			}
		}
	}
	if !found {
		return RouteResult{Serviceable: false, Reason: "no valid route to an accepting laboratory"}, nil
	}
	if bestArr.After(deadline) {
		return RouteResult{Serviceable: false, Reason: "sample cannot reach laboratory before delivery deadline"}, nil
	}
	return RouteResult{
		Serviceable:        true,
		TargetLabID:        bestLab,
		EstimatedArrival:   bestArr,
		RouteLocations:     bestLabPath,
		TotalTravelMinutes: int(bestArr.Sub(earliest).Minutes()),
		TotalCost:          bestLabCost,
		Cooled:             requiresCooled,
	}, nil
}","path":"/workspace/backend/internal/serviceability/engine.go"}

