import (
	"context"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// SeedDefaultSampleTypes inserts the four default sample types if absent.
func (s *Store) SeedDefaultSampleTypes(ctx context.Context, tx pgx.Tx) error {
	defaults := []SampleType{
		{Name: "Amber", ContainerType: "standard"},
		{Name: "Indigo", ContainerType: "standard"},
		{Name: "Frost", RequiresCooledRoute: true, ContainerType: "cooled"},
		{Name: "Pulse", BatchingAllowed: false, ContainerType: "standard"},
	}
	for _, d := range defaults {
		d.QualifiedCollectorRequired = true
		d.RequiredQualification = string(d.Name[0]) // A, I, F, P
		existing, err := s.SampleTypeByName(ctx, d.Name)
		if err == nil && existing != nil {
			continue
		}
		st := d
		st.SampleTypeID = uuid.New()
		if err := s.CreateSampleType(ctx, tx, &st); err != nil {
			return err
		}
	}
	// Set Indigo incompatible with Amber (resolved after both exist).
	amber, _ := s.SampleTypeByName(ctx, "Amber")
	indigo, _ := s.SampleTypeByName(ctx, "Indigo")
	if amber != nil && indigo != nil {
		_, err := tx.Exec(ctx, "UPDATE sample_types SET incompatible_sample_types=ARRAY[$2] WHERE sample_type_id=$1",
			indigo.SampleTypeID, amber.SampleTypeID)
		if err != nil {
			return err
		}
	}
	return nil
}","path":"/workspace/backend/internal/store/seed.go"}

{"command":"create","file_text":"package httpapi

import (
	"net/http"

	"github.com/labsample/app/internal/audit"
	"github.com/labsample/app/internal/serviceability"
	"github.com/labsample/app/internal/store"
	"go.mongodb.org/mongo-driver/mongo"
)

// Server holds application dependencies wired into HTTP handlers.
type Server struct {
	Store   *store.Store
	Mongo   *mongo.Database
	Audit   *audit.Store
	Engine  *serviceability.Engine
	Snap    *serviceability.SnapshotManager
	Mux     *http.ServeMux
}

// New constructs a Server with all dependencies.
func New(s *store.Store, mdb *mongo.Database) *Server {
	srv := &Server{
		Store: s,
		Mongo: mdb,
		Audit: audit.New(mdb),
		Engine: serviceability.New(s),
		Snap:   serviceability.NewSnapshotManager(s),
		Mux:    http.NewServeMux(),
	}
	srv.registerRoutes()
	return srv
}

// routes returns the HTTP mux.
func (s *Server) routes() http.Handler {
	return s.Mux
}

func (s *Server) registerRoutes() {
	m := s.Mux

	// Auth (public)
	m.HandleFunc("POST /api/authenticate-user", s.handleAuthenticate)
	m.HandleFunc("POST /api/auth/logout", s.handleLogout)
	m.HandleFunc("GET /api/auth/session", s.handleSession)
	m.HandleFunc("POST /api/auth/select-role", s.handleSelectRole)

	// Readiness
	m.HandleFunc("GET /ready", s.handleReady)

	// User & profile
	m.HandleFunc("GET /api/users/me", s.handleReadUser)
	m.HandleFunc("PATCH /api/users/me/location", s.handleRecordWorkerLocation)

	// Admin: users management
	m.HandleFunc("POST /api/admin/users", s.adminOnly(s.handleAdminCreateUser))
	m.HandleFunc("GET /api/admin/users", s.adminOnly(s.handleAdminListUsers))
	m.HandleFunc("PATCH /api/admin/users/{userId}", s.adminOnly(s.handleAdminUpdateUser))
	m.HandleFunc("POST /api/admin/users/{userId}/roles", s.adminOnly(s.handleAdminAssignRole))
	m.HandleFunc("DELETE /api/admin/users/{userId}/roles/{role}", s.adminOnly(s.handleAdminRemoveRole))
	m.HandleFunc("POST /api/admin/users/{userId}/certifications", s.adminOnly(s.handleAdminAddCert))
	m.HandleFunc("POST /api/admin/users/{userId}/node-assignment", s.adminOnly(s.handleAdminAssignNode))
	m.HandleFunc("POST /api/admin/users/{userId}/lab-assignment", s.adminOnly(s.handleAdminAssignLab))

	// Admin: network config
	m.HandleFunc("POST /api/admin/locations", s.adminOnly(s.handleCreateLocation))
	m.HandleFunc("GET /api/locations", s.anyRole(s.handleListLocations))
	m.HandleFunc("PATCH /api/admin/locations/{locationId}", s.adminOnly(s.handleUpdateLocation))
	m.HandleFunc("POST /api/admin/locations/{locationId}/status", s.adminOnly(s.handleSetLocationStatus))
	m.HandleFunc("POST /api/admin/locations/{locationId}/function-status", s.adminOnly(s.handleSetLocationFunctionStatus))
	m.HandleFunc("POST /api/admin/connections", s.adminOnly(s.handleCreateConnection))
	m.HandleFunc("GET /api/connections", s.anyRole(s.handleListConnections))
	m.HandleFunc("POST /api/admin/connections/{connectionId}/status", s.adminOnly(s.handleSetConnectionStatus))
	m.HandleFunc("POST /api/admin/sample-types", s.adminOnly(s.handleCreateSampleType))
	m.HandleFunc("GET /api/sample-types", s.anyRole(s.handleListSampleTypes))
	m.HandleFunc("PATCH /api/admin/sample-types/{sampleTypeId}", s.adminOnly(s.handleUpdateSampleType))
	m.HandleFunc("POST /api/admin/laboratories/{locationId}/acceptance", s.adminOnly(s.handleConfigLabAcceptance))
	m.HandleFunc("POST /api/admin/capacity/{resourceId}", s.adminOnly(s.handleConfigureCapacity))
	m.HandleFunc("GET /api/capacity/{resourceId}", s.anyRole(s.handleGetCapacity))

	// Serviceability
	m.HandleFunc("POST /api/serviceability/check", s.requesterOrDispatcher(s.handleCheckServiceability))
	m.HandleFunc("GET /api/serviceability/snapshot", s.anyRole(s.handleReadServiceabilitySnapshot))
	m.HandleFunc("POST /api/admin/serviceability/recompute", s.adminOrDispatcher(s.handleRecomputeServiceability))

	// Requests & samples
	m.HandleFunc("POST /api/requests", s.requesterOnly(s.handleCreateRequest))
	m.HandleFunc("GET /api/requests", s.requesterOnly(s.handleListRequests))
	m.HandleFunc("GET /api/requests/{requestId}", s.requesterOrDispatcher(s.handleGetRequest))
	m.HandleFunc("GET /api/samples", s.dispatcherOrLab(s.handleListSamples))
	m.HandleFunc("GET /api/samples/{sampleId}", s.anyRole(s.handleGetSample))
	m.HandleFunc("GET /api/samples/{sampleId}/state", s.anyRole(s.handleReadSampleState))
	m.HandleFunc("GET /api/samples/{sampleId}/lifecycle", s.anyRole(s.handleReadSampleLifecycle))
	m.HandleFunc("GET /api/samples/{sampleId}/timeline", s.anyRole(s.handleReadSampleTimeline))

	// Journeys
	m.HandleFunc("GET /api/journeys/{journeyId}/plan", s.anyRole(s.handleReadJourneyPlan))
	m.HandleFunc("POST /api/journeys/{journeyId}/split", s.dispatcherOnly(s.handleSplitJourney))
	m.HandleFunc("POST /api/journeys/merge", s.dispatcherOnly(s.handleMergeJourneys))
	m.HandleFunc("POST /api/journeys/{journeyId}/reroute", s.dispatcherOnly(s.handleRerouteJourney))
	m.HandleFunc("POST /api/journeys/{journeyId}/cancel", s.dispatcherOnly(s.handleCancelJourney))
	m.HandleFunc("POST /api/journeys/{journeyId}/replan", s.dispatcherOnly(s.handleReplanJourney))

	// Operations state (dispatcher/admin)
	m.HandleFunc("GET /api/operations/state", s.dispatcherOnly(s.handleReadOperationsState))

	// Assignments & work
	m.HandleFunc("GET /api/work/collection", s.collectionProOnly(s.handleListCollectionWork))
	m.HandleFunc("GET /api/work/transport", s.deliveryOnly(s.handleListTransportWork))
	m.HandleFunc("GET /api/work/node", s.nodeHandlerOnly(s.handleListNodeWork))
	m.HandleFunc("GET /api/work/laboratory", s.labOnly(s.handleListLabWork))
	m.HandleFunc("POST /api/assignments/{assignmentId}/accept", s.workerOnly(s.handleAcceptAssignment))
	m.HandleFunc("POST /api/assignments/{assignmentId}/decline", s.workerOnly(s.handleDeclineAssignment))
	m.HandleFunc("POST /api/assignments/{assignmentId}/collect", s.collectionProOnly(s.handleRecordCollection))
	m.HandleFunc("POST /api/assignments/{assignmentId}/progress", s.deliveryOnly(s.handleRecordProgress))
	m.HandleFunc("POST /api/assignments/{assignmentId}/handoff", s.workerOnly(s.handleInitiateHandoff))
	m.HandleFunc("POST /api/handoffs/{handoffId}/confirm", s.workerOnly(s.handleConfirmHandoff))
	m.HandleFunc("POST /api/samples/{sampleId}/checkpoint", s.workerOnly(s.handleRecordCheckpoint))

	// Pre-sealed samples
	m.HandleFunc("POST /api/samples/presealed", s.workerOrDispatcher(s.handleIngestPresealed))

	// Capacity for node handlers / lab operators
	m.HandleFunc("PATCH /api/node-capacity/{nodeId}", s.nodeHandlerOnly(s.handleConfigureNodeCapacity))
	m.HandleFunc("PATCH /api/lab-capacity/{labId}", s.labOnly(s.handleConfigureLabCapacity))

	// Laboratory receipt
	m.HandleFunc("POST /api/laboratory/{laboratoryId}/receive", s.labOnly(s.handleReceiveSample))
	m.HandleFunc("POST /api/laboratory/{laboratoryId}/exception", s.labOnly(s.handleRecordLabException))

	// Disruptions
	m.HandleFunc("POST /api/disruptions", s.dispatcherOnly(s.handleDeclareDisruption))

	// Audit
	m.HandleFunc("GET /api/audit/search", s.dispatcherOnly(s.handleSearchAudit))
	m.HandleFunc("GET /api/audit/samples/{sampleId}", s.anyRole(s.handleSampleAudit))

	// Realtime
	m.HandleFunc("GET /api/realtime/events", s.anyRole(s.handleStreamRealtimeEvents))

	// Map
	m.HandleFunc("GET /api/map/state", s.anyRole(s.handleMapState))
}

// role wrappers ---------------------------------------------------------------

func (s *Server) adminOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleAdministrator)(h).ServeHTTP
}
func (s *Server) adminOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleAdministrator, RoleDispatcher)(h).ServeHTTP
}
func (s *Server) dispatcherOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) requesterOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleRequester)(h).ServeHTTP
}
func (s *Server) requesterOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleRequester, RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) collectionProOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleCollectionProfessional)(h).ServeHTTP
}
func (s *Server) deliveryOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDeliveryPartner)(h).ServeHTTP
}
func (s *Server) nodeHandlerOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleNodeHandler)(h).ServeHTTP
}
func (s *Server) labOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleLaboratoryTeam)(h).ServeHTTP
}
func (s *Server) workerOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleCollectionProfessional, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)(h).ServeHTTP
}
func (s *Server) workerOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleCollectionProfessional, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam, RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) dispatcherOrLab(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDispatcher, RoleAdministrator, RoleLaboratoryTeam)(h).ServeHTTP
}

// anyRole requires authentication but accepts any selected role.
func (s *Server) anyRole(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		pr := principalFrom(r)
		if pr == nil {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "not authenticated")
			return
		}
		if pr.Role == "" {
			writeErr(w, http.StatusConflict, "role_not_selected", "no active role selected")
			return
		}
		h(w, r)
	}
}

// Role constants local to this package (mirroring store roles for guard usage).
const (
	RoleAdministrator         = "administrator"
	RoleDispatcher             = "dispatcher"
	RoleRequester              = "requester"
	RoleCollectionProfessional = "collection_professional"
	RoleDeliveryPartner        = "delivery_partner"
	RoleNodeHandler            = "node_handler"
	RoleLaboratoryTeam         = "laboratory_team"
)","path":"/workspace/backend/internal/httpapi/server.go"}

