)

// principal builds a Principal for an in-memory user (used during sign-in,
// before a request context principal exists).
func principal(u *store.User, role string) *Principal {
	return &Principal{User: u, Role: role}
}

// auditEntry converts a principal into an audit Entry.
func auditEntry(pr *Principal, action, entityType, entityID string, success bool, outcome string) audit.Entry {
	e := audit.Entry{
		Action: action, EntityType: entityType, EntityID: entityID,
		Success: success, Outcome: outcome, At: time.Now().UTC(),
	}
	if pr != nil && pr.User != nil {
		e.ActorID = pr.User.UserID.String()
		e.Role = pr.Role
	}
	return e
}

// coordPtr builds a coordinate object from lat/lon pointers.
func coordObj(lat, lon *float64) any {
	if lat == nil || lon == nil {
		return nil
	}
	return map[string]any{"latitude": *lat, "longitude": *lon}
}

func fnStates(f store.LocationFunction) map[string]any {
	return map[string]any{
		"collection_point": f.CollectionPoint,
		"transfer_point":  f.TransferPoint,
		"hub":             f.Hub,
		"laboratory":      f.Laboratory,
	}
}

func parseFns(list []string) store.LocationFunction {
	var f store.LocationFunction
	for _, fn := range list {
		switch fn {
		case "collection_point":
			f.CollectionPoint = true
		case "transfer_point":
			f.TransferPoint = true
		case "hub":
			f.Hub = true
		case "laboratory":
			f.Laboratory = true
		}
	}
	return f
}

func locationResponse(l *store.Location) map[string]any {
	return map[string]any{
		"locationId":      l.LocationID.String(),
		"name":            l.Name,
		"coordinate":      map[string]any{"latitude": l.Lat, "longitude": l.Lon},
		"coverageKm":      l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes,
		"active":          l.Active,
		"functions":       fnStates(l.Functions),
	}
}

// sampleTypeResponse builds the JSON view of a sample type.
func sampleTypeResponse(st *store.SampleType) map[string]any {
	incompat := []string{}
	for _, id := range st.IncompatibleSampleTypes {
		incompat = append(incompat, id.String())
	}
	resp := map[string]any{
		"sampleTypeId":              st.SampleTypeID.String(),
		"name":                      st.Name,
		"qualifiedCollectorRequired": st.QualifiedCollectorRequired,
		"requiredQualification":     st.RequiredQualification,
		"containerType":             st.ContainerType,
		"incompatibleSampleTypes":   incompat,
		"requiresCooledRoute":       st.RequiresCooledRoute,
		"batchingAllowed":           st.BatchingAllowed,
	}
	if st.TemperatureMinC != nil {
		resp["temperatureMinC"] = *st.TemperatureMinC
	} else {
		resp["temperatureMinC"] = 0
	}
	if st.TemperatureMaxC != nil {
		resp["temperatureMaxC"] = *st.TemperatureMaxC
	} else {
		resp["temperatureMaxC"] = 0
	}
	return resp
}

// capacityResponse builds the JSON view of a capacity pool.
func capacityResponse(c *store.Capacity) map[string]any {
	avail := c.CapacityUnits - c.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := c.CooledCapacityUnits - c.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return map[string]any{
		"capacityUnits":        c.CapacityUnits,
		"reservedUnits":        c.ReservedUnits,
		"availableUnits":       avail,
		"cooledCapacityUnits":  c.CooledCapacityUnits,
		"cooledReservedUnits": c.CooledReservedUnits,
		"cooledAvailableUnits": cooledAvail,
	}
}

// parseIDs parses a slice of uuid strings.
func parseIDs(list []string) ([]uuid.UUID, bool) {
	out := make([]uuid.UUID, 0, len(list))
	for _, s := range list {
		if s == "" {
			continue
		}
		id, err := uuid.Parse(s)
		if err != nil {
			return nil, false
		}
		out = append(out, id)
	}
	return out, true
}

// writeCreated writes a 201 with the data envelope.
func writeCreated(w http.ResponseWriter, v any) { writeData(w, http.StatusCreated, v) }

// okIfEmpty writes 200 {} helper.
func okIfEmpty(w http.ResponseWriter) { writeData(w, http.StatusOK, map[string]any{}) }

