func (s *Server) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Name            string         `json:"name"`
		Coordinate      map[string]float64 `json:"coordinate"`
		CoverageKm      *float64       `json:"coverageKm"`
		HandlingMinutes *int           `json:"handlingMinutes"`
		Active          bool           `json:"active"`
		Functions       []string       `json:"functions"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.Name == "" || req.Coordinate == nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "name and coordinate required")
		return
	}
	lat := req.Coordinate["latitude"]
	lon := req.Coordinate["longitude"]
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
	}
	fns := parseFns(req.Functions)
	var loc *store.Location
	err := withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		l, err := s.Store.CreateLocation(r.Context(), tx, req.Name, lat, lon, coverage, handling, req.Active, fns)
		if err != nil {
			return err
		}
		loc = l
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusConflict, "conflict", "could not create location")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "create_location", "location", loc.LocationID.String(), true, ""))
	writeCreated(w, locationResponse(loc))
