	return err
}

// AssignmentsBySample returns all assignments for a sample ordered by sequence.
func (s *Store) AssignmentsBySample(ctx context.Context, sampleID uuid.UUID) ([]*Assignment, error) {
	rows, err := s.PG.Query(ctx, `SELECT assignment_id, journey_id, sample_id, kind, sequence, status, from_location_id,
		to_location_id, worker_id, offered_worker_id, node_id, laboratory_id, cooled FROM assignments WHERE sample_id=$1 ORDER BY sequence`, sampleID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Assignment
	for rows.Next() {
		var a Assignment
		if err := rows.Scan(&a.AssignmentID, &a.JourneyID, &a.SampleID, &a.Kind, &a.Sequence, &a.Status, &a.FromLocation,
			&a.ToLocation, &a.WorkerID, &a.OfferedWorkerID, &a.NodeID, &a.LaboratoryID, &a.Cooled); err != nil {
			return nil, err
		}
		out = append(out, &a)
	}
	return out, nil
}

// AssignmentProgress records a progress/status event for an assignment.
type AssignmentProgress struct {
	ProgressID uuid.UUID
	Status     string
	OccurredAt time.Time
	Note       string
}

func (s *Store) RecordAssignmentProgress(ctx context.Context, tx pgx.Tx, assignmentID uuid.UUID, status, note string, at time.Time) error {
	id := uuid.New()
	_, err := tx.Exec(ctx, `INSERT INTO assignment_progress (progress_id, assignment_id, status, occurred_at, note)
		VALUES ($1,$2,$3,$4,$5)`, id, assignmentID, status, at, note)
	return err
}

func (s *Store) AssignmentProgressHistory(ctx context.Context, assignmentID uuid.UUID) ([]AssignmentProgress, error) {
	rows, err := s.PG.Query(ctx, "SELECT progress_id, status, occurred_at, note FROM assignment_progress WHERE assignment_id=$1 ORDER BY occurred_at", assignmentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []AssignmentProgress
	for rows.Next() {
		var p AssignmentProgress
		if err := rows.Scan(&p.ProgressID, &p.Status, &p.OccurredAt, &p.Note); err != nil {
			return nil, err
		}
		out = append(out, p)
	}
	return out, nil
}

// CheckpointsBySample returns all checkpoints for a sample.
type Checkpoint struct {
	CheckpointID uuid.UUID
	AssignmentID *uuid.UUID
	LocationID   *uuid.UUID
	ContainerType string
	ObservedTemp  *float64
	Compliant     bool
	RecordedAt    time.Time
}

func (s *Store) CheckpointsBySample(ctx context.Context, sampleID uuid.UUID) ([]Checkpoint, error) {
	rows, err := s.PG.Query(ctx, `SELECT checkpoint_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at
		FROM checkpoints WHERE sample_id=$1 ORDER BY recorded_at`, sampleID)
	if err != nil {
