}

// ReserveCapacity increments a resource's reserved units.
func (s *Store) ReserveCapacity(ctx context.Context, tx pgx.Tx, resourceID uuid.UUID, journeyID uuid.UUID, assignmentID *uuid.UUID, cooled bool, units int) error {
	id := uuid.New()
	col := "reserved_units"
	if cooled {
		col = "cooled_reserved_units"
	}
	_, err := tx.Exec(ctx, "UPDATE capacity SET "+col+"="+col+"+$4 WHERE resource_id=$1", resourceID, nil, nil, units)
	if err != nil {
		return err
	}
	_, err = tx.Exec(ctx, `INSERT INTO capacity_reservations (reservation_id, resource_id, journey_id, assignment_id, units, cooled)
		VALUES ($1,$2,$3,$4,$5,$6)`, id, resourceID, journeyID, assignmentID, units, cooled)
	return err
}

// ReleaseCapacity decrements a resource's reserved units for a journey.
func (s *Store) ReleaseCapacity(ctx context.Context, tx pgx.Tx, journeyID uuid.UUID) error {
	rows, err := tx.Query(ctx, "SELECT resource_id, units, cooled FROM capacity_reservations WHERE journey_id=$1", journeyID)
	if err != nil {
		return err
	}
	type res struct {
		ResourceID uuid.UUID
		Units      int
		Cooled     bool
	}
	var rels []res
	for rows.Next() {
		var r res
		_ = rows.Scan(&r.ResourceID, &r.Units, &r.Cooled)
		rels = append(rels, r)
	}
	rows.Close()
	for _, r := range rels {
		col := "reserved_units"
		if r.Cooled {
			col = "cooled_reserved_units"
		}
		_, err := tx.Exec(ctx, "UPDATE capacity SET "+col+"=GREATEST("+col+"-$2, 0) WHERE resource_id=$1", r.ResourceID, r.Units)
		if err != nil {
			return err
		}
	}
	_, err = tx.Exec(ctx, "DELETE FROM capacity_reservations WHERE journey_id=$1", journeyID)
	return err
