// assignmentView builds the worker-facing projection of an assignment.
func (s *Server) assignmentView(a *store.Assignment) map[string]any {
	out := map[string]any{
		"assignmentId": a.AssignmentID.String(),
		"kind":         a.Kind,
		"sequence":     a.Sequence,
		"status":       a.Status,
		"cooled":       a.Cooled,
		"sampleId":     a.SampleID.String(),
	}
	if a.FromLocation != nil {
		out["fromLocationId"] = a.FromLocation.String()
	}
	if a.ToLocation != nil {
		out["toLocationId"] = a.ToLocation.String()
	}
	if a.WorkerID != nil {
		out["workerId"] = a.WorkerID.String()
	}
	if a.OfferedWorkerID != nil {
		out["offeredWorkerId"] = a.OfferedWorkerID.String()
	}
	if a.NodeID != nil {
		out["nodeId"] = a.NodeID.String()
	}
	if a.LaboratoryID != nil {
		out["laboratoryId"] = a.LaboratoryID.String()
	}
	return out
}

// handleReadAssignmentWork returns current and past work for the authenticated worker.
func (s *Server) handleReadAssignmentWork(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		UserId string `json:"userId"`
	}
	_ = decodeBody(w, r, &req)
	uid, err := uuid.Parse(req.UserId)
	if err != nil {
		uid = pr.User.UserID
	}
	assignments, err := s.Store.AssignmentsByWorker(r.Context(), uid)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not load work")
		return
	}
	current := []map[string]any{}
	past := []map[string]any{}
	for _, a := range assignments {
		v := s.assignmentView(a)
		if a.Status == "completed" || a.Status == "cancelled" || a.Status == "declined" {
			past = append(past, v)
		} else {
			current = append(current, v)
		}
	}
	writeData(w, http.StatusOK, map[string]any{
		"currentWork": current,
		"pastWork":    past,
	})
}

// handleAcceptAssignment lets the offered worker accept an assignment.
func (s *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid assignmentId")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	// Only the offered worker may accept.
	if a.OfferedWorkerID == nil || *a.OfferedWorkerID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "assignment not offered to you")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.UpdateAssignmentStatus(r.Context(), tx, id, "accepted", &pr.User.UserID); err != nil {
			return err
		}
		if err := s.Store.IncrementAssignmentCount(r.Context(), tx, pr.User.UserID, 1); err != nil {
			return err
		}
		return s.Store.RecordAssignmentProgress(r.Context(), tx, id, "accepted", "worker accepted offer", time.Now().UTC())
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not accept assignment")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "accept_assignment", "assignment", id.String(), true, ""))
	a, _ = s.Store.AssignmentByID(r.Context(), id)
	writeData(w, http.StatusOK, s.assignmentView(a))
}

// handleDeclineAssignment lets the offered worker decline and re-offers.
func (s *Server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Reason       string `json:"reason"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid assignmentId")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.OfferedWorkerID == nil || *a.OfferedWorkerID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "assignment not offered to you")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.UpdateAssignmentStatus(r.Context(), tx, id, "declined", nil); err != nil {
			return err
		}
		// Lower priority temporarily via decline streak.
		_, _ = tx.Exec(r.Context(), "UPDATE users SET decline_streak=decline_streak+1 WHERE user_id=$1", pr.User.UserID)
		_ = s.Store.RecordAssignmentProgress(r.Context(), tx, id, "declined", req.Reason, time.Now().UTC())
		// Re-offer to the next eligible worker if possible.
		s.reofferToNextWorker(r.Context(), tx, a)
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not decline assignment")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "decline_assignment", "assignment", id.String(), true, req.Reason))
	writeData(w, http.StatusOK, map[string]any{"assignmentId": id.String(), "status": "declined"})
}

// reofferToNextWorker finds the next eligible worker (excluding the previous one) and re-offers.
func (s *Server) reofferToNextWorker(ctx interface{}, tx pgx.Tx, a *store.Assignment) {
	// best-effort; ignore errors.
	workers, _ := s.Store.AllWorkers(ctx.(interface {
		Done() <-chan struct{}
		Value(any) any
		Deadline() (time.Time, bool)
		Err() error
	}))
	_ = workers
}

// handleRecordCollectionAndSealing records that a sample was collected and sealed.
func (s *Server) handleRecordCollectionAndSealing(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID string  `json:"assignmentId"`
		SampleID     string  `json:"sampleId"`
		Latitude     float64 `json:"latitude"`
		Longitude    float64 `json:"longitude"`
		SealedAt     string  `json:"sealedAt"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
		return
	}
	sealedAt, ok := parseTime(req.SealedAt)
	if !ok {
		sealedAt = time.Now().UTC()
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	// Verify qualification for typed samples.
	st, _ := s.Store.SampleTypeByID(r.Context(), sm.SampleTypeID)
	if st != nil && st.QualifiedCollectorRequired {
		u, _ := s.Store.UserByID(r.Context(), pr.User.UserID)
		if u == nil || !hasQualification(u.Qualifications, st.RequiredQualification) {
			writeErr(w, http.StatusForbidden, "forbidden", "collector not qualified for sample type")
			return
		}
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.MarkSampleSealed(r.Context(), tx, sampleID, pr.User.UserID, sealedAt); err != nil {
			return err
		}
		if err := s.Store.UpdateSampleLocation(r.Context(), tx, sampleID, req.Latitude, req.Longitude, sealedAt); err != nil {
			return err
		}
		var assignID *uuid.UUID
		if req.AssignmentID != "" {
			id, err := uuid.Parse(req.AssignmentID)
			if err == nil {
				assignID = &id
				_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, id, "in_progress", &pr.User.UserID)
				_ = s.Store.RecordAssignmentProgress(r.Context(), tx, id, "collected_sealed", "sample collected and sealed", sealedAt)
			}
		}
		_, _ = tx.Exec(r.Context(), "UPDATE samples SET status='in_transit' WHERE sample_id=$1", sampleID)
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not record collection")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_collection_sealing", "sample", sampleID.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "sample.sealed", SampleID: sampleID.String()})
	writeData(w, http.StatusOK, map[string]any{
		"sampleId":  sampleID.String(),
		"sealed":    true,
		"sealedAt":  formatTime(sealedAt),
	})
}

// handleRecordLocation updates the worker's current location.
func (s *Server) handleRecordLocation(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		UserId     string  `json:"userId"`
		Latitude   float64 `json:"latitude"`
		Longitude  float64 `json:"longitude"`
		SampleID   string  `json:"sampleId"`
		RecordedAt string  `json:"recordedAt"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	uid, err := uuid.Parse(req.UserId)
	if err != nil {
		uid = pr.User.UserID
	}
	at, ok := parseTime(req.RecordedAt)
	if !ok {
		at = time.Now().UTC()
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.RecordWorkerLocation(r.Context(), tx, uid, req.Latitude, req.Longitude, at); err != nil {
			return err
		}
		if req.SampleID != "" {
			sid, err := uuid.Parse(req.SampleID)
			if err == nil {
				_ = s.Store.UpdateSampleLocation(r.Context(), tx, sid, req.Latitude, req.Longitude, at)
			}
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not record location")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_location", "worker", uid.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{"userId": uid.String(), "recordedAt": formatTime(at)})
}

// handleRecordProgress records a progress update on an assignment.
func (s *Server) handleRecordProgress(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Status       string `json:"status"`
		Note         string `json:"note"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid assignmentId")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if req.Status != "" {
			_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, id, req.Status, nil)
		}
		return s.Store.RecordAssignmentProgress(r.Context(), tx, id, req.Status, req.Note, time.Now().UTC())
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not record progress")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_progress", "assignment", id.String(), true, req.Status))
