// handleReadSampleState returns the current state of a single sample.
func (s *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request, sampleIDStr string) {
	pr := principalFrom(r)
	id, err := uuid.Parse(sampleIDStr)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), id)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	// Requesters can only see their own samples.
	if pr.HasRole(string(store.RoleRequester)) && !pr.HasRole(string(store.RoleDispatcher)) && !pr.HasRole(string(store.RoleAdministrator)) {
		if sm.RequesterID != pr.User.UserID {
			writeErr(w, http.StatusForbidden, "forbidden", "not your sample")
			return
		}
	}
	assignments, _ := s.Store.AssignmentsBySample(r.Context(), id)
	stops := []map[string]any{}
	journeyIDStr := ""
	if sm.ActiveJourneyID != nil {
		journeyIDStr = sm.ActiveJourneyID.String()
		st, _ := s.Store.StopsByJourney(r.Context(), *sm.ActiveJourneyID)
		for _, stp := range st {
			stops = append(stops, map[string]any{
				"locationId":   stp.LocationID.String(),
				"stopType":     stp.StopType,
				"sequence":     stp.Sequence,
				"estimatedAt":  formatTime(stp.EstimatedAt),
			})
		}
	}
	legViews := []map[string]any{}
	for _, a := range assignments {
		legViews = append(legViews, s.assignmentView(a))
	}
	resp := s.sampleSummary(sm)
	resp["journeyId"] = journeyIDStr
	resp["stops"] = stops
	resp["assignments"] = legViews
	s.Audit.Record(r.Context(), auditEntry(pr, "read_sample_state", "sample", id.String(), true, ""))
	writeData(w, http.StatusOK, resp)
}

// handleReadSampleLifecycle returns the full lifecycle/audit timeline for a sample.
func (s *Server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), id)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	assignments, _ := s.Store.AssignmentsBySample(r.Context(), id)
	checkpoints, _ := s.Store.CheckpointsBySample(r.Context(), id)
	// Audit entries for this sample.
	entries, _, _ := s.Audit.Search(r.Context(), audit.Filter{EntityType: "sample", EntityID: id.String(), Limit: 200, Order: "asc"})

	lifecycle := []map[string]any{}
	if sm.SealedAt != nil {
		lifecycle = append(lifecycle, map[string]any{"event": "sealed", "at": formatTime(*sm.SealedAt)})
	}
	for _, cp := range checkpoints {
		lifecycle = append(lifecycle, map[string]any{
			"event":       "checkpoint",
			"checkpointId": cp.CheckpointID.String(),
			"containerType": cp.ContainerType,
			"compliant":    cp.Compliant,
			"at":           formatTime(cp.RecordedAt),
		})
	}
	for _, a := range assignments {
		hist, _ := s.Store.AssignmentProgressHistory(r.Context(), a.AssignmentID)
		for _, p := range hist {
			lifecycle = append(lifecycle, map[string]any{
				"event":        "assignment_progress",
				"assignmentId": a.AssignmentID.String(),
				"kind":         a.Kind,
				"status":       p.Status,
				"note":         p.Note,
				"at":           formatTime(p.OccurredAt),
			})
		}
	}
	for _, e := range entries {
		lifecycle = append(lifecycle, map[string]any{
			"event":     "audit",
			"action":    e.Action,
			"actorId":   e.ActorID,
			"role":      e.Role,
			"at":        formatTime(e.At),
			"outcome":   e.Outcome,
		})
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "read_sample_lifecycle", "sample", id.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{
		"sampleId":  id.String(),
		"status":    sm.Status,
		"lifecycle": lifecycle,
	})
}

