)

// assignmentLeg builds the JourneyLeg projection for an assignment.
func assignmentLeg(a *store.Assignment) map[string]any {
	m := map[string]any{
		"assignmentId": a.AssignmentID.String(),
		"sequence":     a.Sequence,
		"status":       a.Status,
	}
	if a.FromLocation != nil {
		m["fromLocationId"] = a.FromLocation.String()
	}
	if a.ToLocation != nil {
		m["toLocationId"] = a.ToLocation.String()
	}
	if a.WorkerID != nil {
		m["workerId"] = a.WorkerID.String()
	}
	m["sampleId"] = a.SampleID.String()
	return m
}

// handleAcceptAssignment lets the offered worker accept an assignment.
func (s *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID  string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.OfferedWorkerID == nil || *a.OfferedWorkerID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "offer_not_offered", "assignment not offered to you")
		return
	}
	if a.Status != "offered" && a.Status != "pending" {
		writeErr(w, http.StatusConflict, "assignment_inactive", "assignment no longer offerable")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.UpdateAssignmentStatus(r.Context(), tx, id, "accepted", &pr.User.UserID); err != nil {
			return err
		}
		if err := s.Store.IncrementAssignmentCount(r.Context(), tx, pr.User.UserID, 1); err != nil {
			return err
		}
		return s.Store.RecordAssignmentProgress(r.Context(), tx, id, "accepted", "worker accepted offer", time.Now().UTC())
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not accept assignment")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "accept_assignment", "assignment", id.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "assignment.accepted", EntityType: "assignment", EntityID: id.String()})
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"workerId":     pr.User.UserID.String(),
		"status":       "accepted",
	})
}

// handleDeclineAssignment lets the offered worker decline and re-offers.
func (s *Server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Reason         string `json:"reason"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.OfferedWorkerID == nil || *a.OfferedWorkerID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "offer_not_offered", "assignment not offered to you")
		return
	}
	declinedAt, ok := parseTime(req.DeclinedAt)
	if !ok {
		declinedAt = time.Now().UTC()
	}
	reofferedTo := ""
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		_ = s.Store.RecordAssignmentProgress(r.Context(), tx, id, "declined", req.Reason, declinedAt)
		_, _ = tx.Exec(r.Context(), "UPDATE users SET decline_streak=COALESCE(decline_streak,0)+1 WHERE user_id=$1", pr.User.UserID)
		reofferedTo = s.reofferToNextWorker(r.Context(), tx, a)
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not decline assignment")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "decline_assignment", "assignment", id.String(), true, req.Reason))
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"status":       "pending",
		"declinedBy":   pr.User.UserID.String(),
		"declinedAt":   formatTime(declinedAt),
		"reofferedTo":  reofferedTo,
	})
}

// reofferToNextWorker finds the next eligible worker and re-offers; returns its id ("" if none).
func (s *Server) reofferToNextWorker(ctx context.Context, tx pgx.Tx, a *store.Assignment) string {
	workers, _ := s.Store.AllWorkers(ctx)
	st, _ := s.Store.SampleTypeByID(ctx, a.SampleID)
	prev := uuid.Nil
	if a.OfferedWorkerID != nil {
		prev = *a.OfferedWorkerID
	}
	for _, wid := range workers {
		if wid == prev {
			continue
		}
		if s.pickWorker(ctx, []uuid.UUID{wid}, a, a.Kind, st) == wid {
			_ = s.Store.ReofferAssignment(ctx, tx, a.AssignmentID, wid)
			return wid.String()
		}
	}
	_ = s.Store.SetSampleException(ctx, tx, a.SampleID, "no_qualified_worker", "declined and no other worker available")
	return ""
}

// handleCollectAndSealSample records that a sample was collected and sealed.
func (s *Server) handleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID            string   `json:"sampleId"`
		AssignmentID        string   `json:"assignmentId"`
		CollectedAt         string   `json:"collectedAt"`
		ContainerType       string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	collectedAt, ok := parseTime(req.CollectedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid collectedAt")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if sm.Sealed {
		writeErr(w, http.StatusConflict, "invalid_sample_state", "sample already sealed")
		return
	}
	// Collection must fall inside the collection window.
	if sm.EarliestColl != nil && collectedAt.Before(*sm.EarliestColl) {
		writeErr(w, http.StatusConflict, "outside_collection_window", "collected before earliest collection time")
		return
	}
	if sm.LatestColl != nil && collectedAt.After(*sm.LatestColl) {
		writeErr(w, http.StatusConflict, "outside_collection_window", "collected after latest collection time")
		return
	}
	st, _ := s.Store.SampleTypeByID(r.Context(), sm.SampleTypeID)
	if st != nil && st.QualifiedCollectorRequired {
		u, _ := s.Store.UserByID(r.Context(), pr.User.UserID)
		if u == nil || !hasQualification(u.Qualifications, st.RequiredQualification) {
			writeErr(w, http.StatusForbidden, "forbidden", "collector not qualified for sample type")
			return
		}
	}
	// Handling compliance against sample type container/temperature.
	compliant := true
	if st != nil {
		if req.ContainerType != "" && req.ContainerType != st.ContainerType {
			compliant = false
		}
		if req.ObservedTemperatureC != nil {
			if st.TemperatureMinC != nil && *req.ObservedTemperatureC < *st.TemperatureMinC {
				compliant = false
			}
			if st.TemperatureMaxC != nil && *req.ObservedTemperatureC > *st.TemperatureMaxC {
				compliant = false
			}
		}
	}
	var assignID *uuid.UUID
	if req.AssignmentID != "" {
		id, err := uuid.Parse(req.AssignmentID)
		if err == nil {
			assignID = &id
		}
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.MarkSampleSealed(r.Context(), tx, sampleID, pr.User.UserID, collectedAt); err != nil {
			return err
		}
		if req.ContainerType != "" {
			_, _ = tx.Exec(r.Context(), "UPDATE samples SET container_type=$2 WHERE sample_id=$1", sampleID, req.ContainerType)
		}
		if assignID != nil {
			_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, *assignID, "in_progress", &pr.User.UserID)
			_ = s.Store.RecordAssignmentProgress(r.Context(), tx, *assignID, "collected_sealed", "sample collected and sealed", collectedAt)
		}
		if !compliant {
			_ = s.Store.SetSampleException(r.Context(), tx, sampleID, "handling_breach", "collection container/temperature out of range")
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record collection")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "collect_and_seal", "sample", sampleID.String(), compliant, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "sample.sealed", EntityType: "sample", EntityID: sampleID.String()})
	writeCreated(w, map[string]any{
		"sampleId":           sampleID.String(),
		"status":             "sealed",
		"currentHolderId":    pr.User.UserID.String(),
		"sealedAt":           formatTime(collectedAt),
		"handlingCompliant":  compliant,
	})
}

// handleRecordWorkerLocation records the worker's current location (tied to an assignment).
func (s *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID string             `json:"assignmentId"`
		Coordinate   map[string]float64 `json:"coordinate"`
		Sequence     int                `json:"sequence"`
		RecordedAt   string             `json:"recordedAt"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	lat := req.Coordinate["latitude"]
	lon := req.Coordinate["longitude"]
	at, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.RecordWorkerLocation(r.Context(), tx, pr.User.UserID, lat, lon, at); err != nil {
			return err
		}
		_ = s.Store.UpdateSampleLocation(r.Context(), tx, a.SampleID, lat, lon, at)
		_ = s.Store.RecordAssignmentProgress(r.Context(), tx, id, "in_transit", "location update", at)
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record location")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_location", "assignment", id.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "worker.location", EntityType: "assignment", EntityID: id.String()})
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"coordinate":   map[string]any{"latitude": lat, "longitude": lon},
		"sequence":     req.Sequence,
		"recordedAt":   formatTime(at),
	})
}

// handleUpdateAssignmentProgress records a progress/status event on an assignment.
func (s *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID  string `json:"assignmentId"`
		Status        string `json:"status"`
		OccurredAt    string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	at, ok := parseTime(req.OccurredAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid occurredAt")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if req.Status != "" {
			_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, id, req.Status, nil)
		}
		return s.Store.RecordAssignmentProgress(r.Context(), tx, id, req.Status, "", at)
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record progress")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "update_progress", "assignment", id.String(), true, req.Status))
	s.Audit.Emit(r.Context(), audit.Event{Type: "assignment.progress", EntityType: "assignment", EntityID: id.String()})
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"sampleId":     a.SampleID.String(),
		"status":       req.Status,
	})
}

// handleInitiateHandoff begins a custody handoff from the current holder to a receiver.
func (s *Server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID       string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID string `json:"toAssignmentId"`
		ReceiverID     string `json:"receiverId"`
		InitiatedAt    string `json:"initiatedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	fromID, err := uuid.Parse(req.FromAssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid fromAssignmentId")
		return
	}
	toID, err := uuid.Parse(req.ToAssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid toAssignmentId")
		return
	}
	receiverID, err := uuid.Parse(req.ReceiverID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_receiver", "invalid receiverId")
		return
	}
	initiatedAt, ok := parseTime(req.InitiatedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid initiatedAt")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != pr.User.UserID {
		writeErr(w, http.StatusConflict, "not_current_holder", "you are not the current holder")
		return
	}
	fromA, err := s.Store.AssignmentByID(r.Context(), fromID)
	if err != nil || fromA == nil || fromA.SampleID != sampleID {
		writeErr(w, http.StatusForbidden, "sender_assignment_mismatch", "from assignment does not match sample")
		return
	}
	toA, err := s.Store.AssignmentByID(r.Context(), toID)
	if err != nil || toA == nil || toA.SampleID != sampleID {
		writeErr(w, http.StatusConflict, "receiver_assignment_mismatch", "to assignment does not match sample")
		return
	}
	// No duplicate pending handoff for this sample.
	if existing, _ := s.Store.PendingHandoffForSample(r.Context(), sampleID); existing != nil {
		writeErr(w, http.StatusConflict, "pending_handoff_exists", "a pending handoff already exists")
		return
	}
	h := &store.Handoff{
		SampleID: sampleID, FromAssignmentID: fromID, ToAssignmentID: toID,
		SenderID: pr.User.UserID, ReceiverID: receiverID, InitiatedAt: initiatedAt,
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		return s.Store.CreateHandoff(r.Context(), tx, h)
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not initiate handoff")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "initiate_handoff", "handoff", h.HandoffID.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "handoff.initiated", EntityType: "handoff", EntityID: h.HandoffID.String()})
	writeCreated(w, map[string]any{
		"handoffId":        h.HandoffID.String(),
		"senderId":         pr.User.UserID.String(),
		"receiverId":       receiverID.String(),
		"currentHolderId":  pr.User.UserID.String(),
		"status":           "pending",
	})
}

// handleConfirmHandoff confirms one side of a custody handoff.
func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		HandoffID      string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt    string `json:"confirmedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.HandoffID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid handoffId")
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "confirmationSide must be sender or receiver")
		return
	}
	at, ok := parseTime(req.ConfirmedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid confirmedAt")
		return
	}
	h, err := s.Store.HandoffByID(r.Context(), id)
	if err != nil || h == nil {
		writeErr(w, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	if req.ConfirmationSide == "sender" && h.SenderID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the sender")
		return
	}
	if req.ConfirmationSide == "receiver" && h.ReceiverID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the receiver")
		return
	}
	var updated *store.Handoff
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		hh, err := s.Store.ConfirmHandoffSide(r.Context(), tx, id, req.ConfirmationSide, at)
		if err != nil {
			return err
		}
		updated = hh
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not confirm handoff")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "confirm_handoff", "handoff", id.String(), true, req.ConfirmationSide))
	holderID := updated.SenderID
	if updated.Status == "confirmed" {
		holderID = updated.ReceiverID
		s.Audit.Emit(r.Context(), audit.Event{Type: "custody.transferred", EntityType: "handoff", EntityID: id.String()})
	}
	writeCreated(w, map[string]any{
		"handoffId":         id.String(),
		"status":            updated.Status,
		"senderConfirmed":   updated.SenderConfirmed,
		"receiverConfirmed": updated.ReceiverConfirmed,
		"currentHolderId":  holderID.String(),
	})
}

// handleRecordHandlingCheckpoint records a handling checkpoint for a held sample.
func (s *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID            string   `json:"sampleId"`
		AssignmentID        string   `json:"assignmentId"`
		LocationID          string   `json:"locationId"`
		ContainerType       string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt          string   `json:"recordedAt"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	at, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the current holder")
		return
	}
	var assignID, locID *uuid.UUID
	if req.AssignmentID != "" {
		id, _ := uuid.Parse(req.AssignmentID)
		assignID = &id
	}
	if req.LocationID != "" {
		id, _ := uuid.Parse(req.LocationID)
		locID = &id
	}
	// Compliance with the sample's required container/temperature (from request overrides).
	compliant := true
	if req.ContainerType != "" && sm.ContainerType != "" && req.ContainerType != sm.ContainerType {
		compliant = false
	}
	if req.ObservedTemperatureC != nil {
		if sm.TemperatureMinC != nil && *req.ObservedTemperatureC < *sm.TemperatureMinC {
			compliant = false
		}
		if sm.TemperatureMaxC != nil && *req.ObservedTemperatureC > *sm.TemperatureMaxC {
			compliant = false
		}
	}
	var cpID uuid.UUID
	var sampleStatus string
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		id, err := s.Store.CreateCheckpoint(r.Context(), tx, sampleID, assignID, locID, req.ContainerType, req.ObservedTemperatureC, compliant, at)
		if err != nil {
			return err
		}
		cpID = id
		if !compliant {
			_ = s.Store.SetSampleException(r.Context(), tx, sampleID, "handling_breach", "checkpoint container/temperature out of range")
			sampleStatus = "exception"
		} else {
			sampleStatus = sm.Status
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record checkpoint")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_checkpoint", "checkpoint", cpID.String(), compliant, ""))
	if !compliant {
		s.Audit.Emit(r.Context(), audit.Event{Type: "sample.exception", EntityType: "sample", EntityID: sampleID.String()})
	}
	writeCreated(w, map[string]any{
		"checkpointId": cpID.String(),
		"sampleId":    sampleID.String(),
		"compliant":   compliant,
		"sampleStatus": sampleStatus,
	})
}

// handleConfirmLaboratoryReceipt confirms laboratory receipt of a sample.
func (s *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
