// handleReportDisruption triggers replanning for affected samples.
func (s *Server) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		ResourceType  string `json:"resourceType"`
		ResourceID    string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	occurredAt, ok := parseTime(req.OccurredAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid occurredAt")
		return
	}
	_ = occurredAt
	// Deactivate the affected resource if possible.
	_ = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		switch req.ResourceType {
		case "location", "node", "laboratory":
			if id, err := uuid.Parse(req.ResourceID); err == nil {
				_ = s.Store.SetLocationStatus(r.Context(), tx, id, false)
			}
		case "connection":
			if id, err := uuid.Parse(req.ResourceID); err == nil {
				_ = s.Store.SetConnectionStatus(r.Context(), tx, id, false)
			}
		case "worker":
			if id, err := uuid.Parse(req.ResourceID); err == nil {
				_ = s.Store.SetWorkerAvailability(r.Context(), tx, id, false, 0)
			}
		}
		return nil
	})
	// Find affected samples (those with unfinished assignments using the resource).
	affected := []string{}
	replacementIDs := []string{}
	allJ, _ := s.Store.AllJourneys(r.Context())
	for _, j := range allJ {
		if !j.Active {
			continue
		}
		assignments, _ := s.Store.AssignmentsByJourney(r.Context(), j.JourneyID)
		touched := false
		for _, a := range assignments {
			if a.Status == "completed" {
				continue
			}
			if req.ResourceType == "worker" && a.WorkerID != nil {
				if id, err := uuid.Parse(req.ResourceID); err == nil && *a.WorkerID == id {
					touched = true
				}
			}
			if (req.ResourceType == "location" || req.ResourceType == "node" || req.ResourceType == "laboratory") {
				if id, err := uuid.Parse(req.ResourceID); err == nil {
					if a.FromLocation != nil && *a.FromLocation == id {
						touched = true
					}
					if a.ToLocation != nil && *a.ToLocation == id {
						touched = true
					}
				}
			}
		}
		if touched {
			for _, sid := range j.SampleIDs {
				affected = append(affected, sid.String())
			}
		}
	}
	replanStatus := "not_required"
	if len(affected) > 0 {
		replanStatus = "replaced"
	}
	_ = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		for _, sidStr := range affected {
			sid, _ := uuid.Parse(sidStr)
			_ = s.Store.SetSampleException(r.Context(), tx, sid, "disruption", req.Reason)
		}
		return nil
	})
	disruptionID := uuid.New()
	s.Audit.Record(r.Context(), auditEntry(pr, "report_disruption", req.ResourceType, req.ResourceID, true, req.Reason))
	s.Audit.Emit(r.Context(), audit.Event{Type: "disruption.reported", EntityType: "disruption", EntityID: disruptionID.String()})
	writeCreated(w, map[string]any{
		"disruptionId":        disruptionID.String(),
		"affectedSampleIds":  affected,
		"replacementPlanIds": replacementIDs,
		"replanStatus":       replanStatus,
	})
}

// handleReadOperationsState returns the dispatcher operations dashboard payload.
func (s *Server) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Filters map[string]any `json:"filters"`
	}
	_ = decodeBody(w, r, &req)
	sampleTypeFilter := ""
	if req.Filters != nil {
		if v, ok := req.Filters["sampleTypeId"].(string); ok {
			sampleTypeFilter = v
		} else if v, ok := req.Filters["sample_type_id"].(string); ok {
			sampleTypeFilter = v
		}
	}
	samples, _ := s.Store.AllSamples(r.Context())
	locs, _ := s.Store.AllLocations(r.Context())
	conns, _ := s.Store.AllConnections(r.Context())
	handoffs, _ := s.Store.AllHandoffs(r.Context())

	sampleViews := []map[string]any{}
	for _, sm := range samples {
		if sampleTypeFilter != "" && sm.SampleTypeID.String() != sampleTypeFilter {
			continue
		}
		m := map[string]any{
			"sampleId":         sm.SampleID.String(),
			"status":           sm.Status,
			"requestId":        sm.RequestID.String(),
			"deliveryDeadline": formatTime(sm.DeliveryDeadline),
			"origin":           map[string]any{"latitude": sm.OriginLat, "longitude": sm.OriginLon},
			"locationStale":    sm.LocStale,
		}
		if sm.CurrentHolderID != nil {
			m["currentHolderId"] = sm.CurrentHolderID.String()
		}
		if sm.ActiveJourneyID != nil {
			m["activeJourneyId"] = sm.ActiveJourneyID.String()
		}
		if sm.LatestLat != nil && sm.LatestLon != nil {
			m["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLon}
		}
		if sm.LocRecordedAt != nil {
			m["locationRecordedAt"] = formatTime(*sm.LocRecordedAt)
		}
		sampleViews = append(sampleViews, m)
	}

	// Workers.
	workerIDs, _ := s.Store.AllWorkers(r.Context())
	workerViews := []map[string]any{}
	spread := 0
	for _, wid := range workerIDs {
		w, _ := s.Store.Worker(r.Context(), wid)
		u, _ := s.Store.UserByID(r.Context(), wid)
		status := "unavailable"
		if w != nil && w.Available {
			status = "available"
		}
		cap := 0
		count := 0
		if w != nil {
			cap = w.CapacityUnits
			count = w.AssignedCount
		}
		roles := []string{}
		full := ""
		if u != nil {
			roles = u.Roles
			full = u.FullName
		}
		m := map[string]any{
			"workerId":        wid.String(),
			"available":       status == "available",
			"status":          status,
			"capacityUnits":   cap,
			"assignmentCount": count,
			"locationStale":   true,
			"roles":           roles,
			"fullName":        full,
		}
		lat, lon, at, _ := s.Store.WorkerLatestLocation(r.Context(), wid)
		if lat != nil && lon != nil {
			m["latestLocation"] = map[string]any{"latitude": *lat, "longitude": *lon}
			m["locationStale"] = false
		}
		if at != nil {
			m["locationRecordedAt"] = formatTime(*at)
		}
		workerViews = append(workerViews, m)
		if count > spread {
			spread = count
		}
	}

	locViews := []map[string]any{}
	for _, l := range locs {
		cap, _ := s.Store.GetCapacity(r.Context(), l.LocationID)
		m := map[string]any{
			"id":             l.LocationID.String(),
			"locationId":     l.LocationID.String(),
			"name":           l.Name,
			"coordinate":     map[string]any{"latitude": l.Lat, "longitude": l.Lon},
			"active":         l.Active,
			"coverageKm":     l.CoverageKm,
			"handlingMinutes": l.HandlingMinutes,
			"functions":      fnStates(l.Functions),
		}
		if cap != nil {
			m["capacity"] = capacityResponse(cap)
		}
		locViews = append(locViews, m)
	}

	connViews := []map[string]any{}
	for _, c := range conns {
		cap, _ := s.Store.GetCapacity(r.Context(), c.ConnectionID)
		m := map[string]any{
			"id":             c.ConnectionID.String(),
			"connectionId":   c.ConnectionID.String(),
			"fromLocationId": c.FromLocation.String(),
			"toLocationId":   c.ToLocation.String(),
			"travelMinutes":  c.TravelMinutes,
			"costUnits":      c.CostUnits,
			"cooled":         c.Cooled,
			"active":         c.Active,
		}
		if cap != nil {
			m["capacity"] = capacityResponse(cap)
		}
		connViews = append(connViews, m)
	}

	handoffViews := []map[string]any{}
	for _, h := range handoffs {
		handoffViews = append(handoffViews, map[string]any{
			"handoffId": h.HandoffID.String(),
			"sampleId":  h.SampleID.String(),
			"status":    h.Status,
		})
	}

	exceptions := []map[string]any{}
	for _, sm := range samples {
		if sm.ExceptionKind != nil {
			exceptions = append(exceptions, map[string]any{
				"sampleId":       sm.SampleID.String(),
				"exceptionKind":  *sm.ExceptionKind,
				"exceptionReason": sm.ExceptionReason,
			})
		}
	}

	ineligible := 0
	for _, sm := range samples {
		if sm.ExceptionKind != nil && *sm.ExceptionKind == "no_qualified_worker" {
			ineligible++
		}
	}

	s.Audit.Record(r.Context(), auditEntry(pr, "read_operations_state", "operations", "", true, ""))
	writeData(w, http.StatusOK, map[string]any{
		"samples":                 sampleViews,
		"workers":                 workerViews,
		"locations":               locViews,
		"connections":             connViews,
		"routes":                  []map[string]any{},
		"handoffs":                handoffViews,
		"delays":                  []map[string]any{},
		"exceptions":              exceptions,
		"assignmentCountSpread":   spread,
		"ineligibleAssignmentCount": ineligible,
	})
}

// handleListRoleWork returns current and past work for the selected role.
func (s *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = decodeBody(w, r, &req)
	role := req.Role
	if role == "" {
		role = pr.Role
	}
	// Requester role: show their samples.
	if role == RoleRequester {
		samples, _ := s.Store.SamplesByRequester(r.Context(), pr.User.UserID)
		pending := []map[string]any{}
		inProg := []map[string]any{}
		completed := []map[string]any{}
		for _, sm := range samples {
			item := map[string]any{
				"kind":           "sample",
				"sampleId":       sm.SampleID.String(),
				"requestId":      sm.RequestID.String(),
				"status":         sm.Status,
				"locationStale":  sm.LocStale,
				"history":        s.timelineForSample(r, sm.SampleID, "asc"),
			}
			if sm.DeliveryDeadline.IsZero() == false {
				item["deliveryDeadline"] = formatTime(sm.DeliveryDeadline)
			}
			switch sm.Status {
			case "received":
				completed = append(completed, item)
			case "requested":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
		writeData(w, http.StatusOK, map[string]any{
			"pending": pending, "inProgress": inProg, "completed": completed,
		})
		return
	}
	// Worker roles: show their assignments.
	assignments, _ := s.Store.AssignmentsByWorker(r.Context(), pr.User.UserID)
	pending := []map[string]any{}
	inProg := []map[string]any{}
	completed := []map[string]any{}
	for _, a := range assignments {
		hist, _ := s.Store.AssignmentProgressHistory(r.Context(), a.AssignmentID)
		history := []map[string]any{}
		for i, p := range hist {
			history = append(history, map[string]any{
				"eventId":    i + 1,
				"action":     p.Status,
				"actorId":    pr.User.UserID.String(),
				"role":       role,
				"entityType": "assignment",
				"entityId":   a.AssignmentID.String(),
				"success":    true,
				"occurredAt": formatTime(p.OccurredAt),
				"details":    map[string]any{"note": p.Note},
			})
		}
		item := map[string]any{
			"kind":         a.Kind,
			"assignmentId": a.AssignmentID.String(),
			"sampleId":     a.SampleID.String(),
			"status":       a.Status,
			"history":     history,
		}
		if a.FromLocation != nil {
			item["fromLocationId"] = a.FromLocation.String()
		}
		if a.ToLocation != nil {
			item["toLocationId"] = a.ToLocation.String()
		}
		if a.NodeID != nil {
			item["nodeId"] = a.NodeID.String()
		}
		if a.LaboratoryID != nil {
			item["laboratoryId"] = a.LaboratoryID.String()
		}
		switch a.Status {
		case "completed", "cancelled", "declined":
			completed = append(completed, item)
		case "offered", "pending":
			pending = append(pending, item)
		default:
			inProg = append(inProg, item)
		}
	}
	// Dispatcher role: show journeys.
	if role == RoleDispatcher || role == RoleAdministrator {
		journeys, _ := s.Store.AllJourneys(r.Context())
		for _, j := range journeys {
			sids := []string{}
			for _, sid := range j.SampleIDs {
				sids = append(sids, sid.String())
			}
			assignments, _ := s.Store.AssignmentsByJourney(r.Context(), j.JourneyID)
			est := ""
			if j.EstimatedDelivery != nil {
				est = formatTime(*j.EstimatedDelivery)
			}
			item := map[string]any{
				"kind":             "journey",
				"journeyId":        j.JourneyID.String(),
				"status":           j.Status,
				"routeMode":        j.RouteMode,
				"planVersion":      j.PlanVersion,
				"sampleIds":        sids,
				"estimatedDeliveryAt": est,
				"assignmentCount":  len(assignments),
				"history":          []map[string]any{},
			}
			switch j.Status {
			case "completed", "cancelled":
				completed = append(completed, item)
			case "planned":
				pending = append(pending, item)
			default:
				inProg = append(inProg, item)
			}
		}
	}
	writeData(w, http.StatusOK, map[string]any{
		"pending": pending, "inProgress": inProg, "completed": completed,
	})
}

// handleReadSampleState returns the current state of a single sample.
func (s *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	id, err := uuid.Parse(r.PathValue("sampleId"))
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), id)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	// Requesters can only see their own samples.
	if pr.HasRole(RoleRequester) && !pr.HasRole(RoleDispatcher) && !pr.HasRole(RoleAdministrator) {
		if sm.RequesterID != pr.User.UserID {
			writeErr(w, http.StatusForbidden, "forbidden", "not your sample")
			return
		}
	}
	assignments, _ := s.Store.AssignmentsBySample(r.Context(), id)
	activeIDs := []string{}
	for _, a := range assignments {
		if a.Status != "completed" && a.Status != "cancelled" && a.Status != "declined" {
			activeIDs = append(activeIDs, a.AssignmentID.String())
		}
	}
	incompat := []string{}
	for _, i := range sm.Incompatible {
		incompat = append(incompat, i.String())
	}
	servStr := "serviceable"
	if sm.ExceptionKind != nil {
		servStr = "unserviceable"
	}
	resp := map[string]any{
		"sampleId":             sm.SampleID.String(),
		"requestId":            sm.RequestID.String(),
		"requesterId":          sm.RequesterID.String(),
		"origin":               map[string]any{"latitude": sm.OriginLat, "longitude": sm.OriginLon},
		"originType":           sm.OriginType,
		"requestedAt":          formatTime(sm.RequestedAt),
		"deliveryDeadline":     formatTime(sm.DeliveryDeadline),
		"sampleTypeId":         sm.SampleTypeID.String(),
		"containerType":        sm.ContainerType,
		"temperatureMinC":      sm.TemperatureMinC,
		"temperatureMaxC":      sm.TemperatureMaxC,
		"incompatibleSampleTypes": incompat,
		"serviceability":       servStr,
		"activeAssignmentIds":  activeIDs,
		"state":                map[string]any{"status": sm.Status},
		"timeline":             s.timelineForSample(r, id, "asc"),
		"locationStale":        sm.LocStale,
	}
	if sm.ActiveJourneyID != nil {
		resp["activeJourneyId"] = sm.ActiveJourneyID.String()
	}
	if sm.TargetLabID != nil {
		resp["targetLaboratoryId"] = sm.TargetLabID.String()
	}
	if sm.LatestLat != nil && sm.LatestLon != nil {
		resp["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLon}
	}
	if sm.LocRecordedAt != nil {
		resp["locationRecordedAt"] = formatTime(*sm.LocRecordedAt)
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "read_sample_state", "sample", id.String(), true, ""))
	writeData(w, http.StatusOK, resp)
}

// handleReadSampleLifecycle returns the full lifecycle of a sample.
func (s *Server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), id)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	assignments, _ := s.Store.AssignmentsBySample(r.Context(), id)
	completedLegs := []string{}
	for _, a := range assignments {
		if a.Status == "completed" {
			completedLegs = append(completedLegs, a.AssignmentID.String())
		}
	}
	// Active replacement plans: journeys with parent != nil for this sample.
	replacementIDs := []string{}
	allJ, _ := s.Store.JourneysBySample(r.Context(), id)
	for _, j := range allJ {
		if j.ParentJourneyID != nil && j.Active {
			replacementIDs = append(replacementIDs, j.JourneyID.String())
		}
	}
	resp := map[string]any{
		"sampleId":                id.String(),
		"status":                 sm.Status,
		"sealed":                 sm.Sealed,
		"completedLegIds":        completedLegs,
		"activeReplacementPlanIds": replacementIDs,
		"timeline":               s.timelineForSample(r, id, "asc"),
		"locationStale":          sm.LocStale,
	}
	if sm.CurrentHolderID != nil {
		resp["currentHolderId"] = sm.CurrentHolderID.String()
	}
	if sm.ActiveJourneyID != nil {
		resp["activeJourneyId"] = sm.ActiveJourneyID.String()
	}
	if sm.ReceivedLabID != nil {
		resp["receivedLaboratoryId"] = sm.ReceivedLabID.String()
	}
	if sm.LatestLat != nil && sm.LatestLon != nil {
		resp["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLon}
	}
	if sm.LocRecordedAt != nil {
		resp["locationRecordedAt"] = formatTime(*sm.LocRecordedAt)
	}
	if sm.ExceptionKind != nil {
		resp["exception"] = map[string]any{"kind": *sm.ExceptionKind, "reason": sm.ExceptionReason}
	}
	if ph, _ := s.Store.PendingHandoffForSample(r.Context(), id); ph != nil {
		resp["pendingHandoffId"] = ph.HandoffID.String()
		resp["pendingHandoff"] = map[string]any{
			"handoffId":  ph.HandoffID.String(),
			"senderId":   ph.SenderID.String(),
			"receiverId": ph.ReceiverID.String(),
			"status":     ph.Status,
		}
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "read_sample_lifecycle", "sample", id.String(), true, ""))
	writeData(w, http.StatusOK, resp)
}

// helper: Principal.HasRole.
func (p *Principal) HasRole(role string) bool {
	if p == nil || p.User == nil {
		return false
	}
	for _, r := range p.User.Roles {
		if r == role {
			return true
		}
	}
	return false
}

