// handleSearchAuditTrail searches the audit log.
func (s *Server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   string  `json:"fromTime"`
		ToTime     string  `json:"toTime"`
		Limit      int     `json:"limit"`
		Offset     int     `json:"offset"`
		Order      string  `json:"order"`
	}
	_ = decodeBody(w, r, &req)
	f := audit.Filter{
		Query: req.Query, ActorID: req.ActorID, EntityType: req.EntityType, EntityID: req.EntityID,
		Action: req.Action, Role: req.Role, Success: req.Success,
		Limit: req.Limit, Offset: req.Offset, Order: req.Order,
	}
	if req.FromTime != "" {
		if t, ok := parseTime(req.FromTime); ok {
			f.FromTime = &t
		}
	}
	if req.ToTime != "" {
		if t, ok := parseTime(req.ToTime); ok {
			f.ToTime = &t
		}
	}
	entries, total, err := s.Audit.Search(r.Context(), f)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "audit search failed")
		return
	}
	limit := req.Limit
	if limit <= 0 {
		limit = 50
	}
	out := []map[string]any{}
	for _, e := range entries {
		out = append(out, map[string]any{
			"auditId":     e.EntryID,
			"actorId":     e.ActorID,
			"role":        e.Role,
			"actorRole":   e.Role,
			"action":      e.Action,
			"entityType":  e.EntityType,
			"entityId":    e.EntityID,
			"success":     e.Success,
			"occurredAt":  formatTime(e.At),
			"details":     e.Changes,
		})
	}
	returned := len(out)
	hasMore := req.Offset+returned < int(total)
	nextOffset := req.Offset + returned
	if !hasMore {
		nextOffset = 0
	}
	order := req.Order
	if order == "" {
		order = "newest_first"
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "search_audit", "audit", "", true, req.Query))
	writeData(w, http.StatusOK, map[string]any{
		"entries":    out,
		"total":      total,
		"returned":   returned,
		"offset":     req.Offset,
		"limit":      limit,
		"order":      order,
		"hasMore":    hasMore,
		"nextOffset": nextOffset,
	})
}

// handleStreamRealtimeEvents returns realtime events since a cursor.
func (s *Server) handleStreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	sinceStr := r.URL.Query().Get("since")
	limitStr := r.URL.Query().Get("limit")
	since, _ := strconv.ParseInt(sinceStr, 10, 64)
	limit, _ := strconv.Atoi(limitStr)
	events, maxSeq, err := s.Audit.Events(r.Context(), since, limit)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not load events")
		return
	}
	out := []map[string]any{}
	for _, ev := range events {
		out = append(out, map[string]any{
			"id":         ev.Seq,
			"type":       ev.Type,
			"entityType": ev.Type,
			"entityId":   ev.SampleID,
			"payload":    ev.Data,
			"createdAt":  formatTime(ev.At),
		})
	}
	cursor := maxSeq
	if cursor == 0 {
		cursor = since
	}
	writeData(w, http.StatusOK, map[string]any{
		"events": out,
		"cursor": cursor,
	})
}

// handleReadUIBootstrap returns data the frontend needs to bootstrap.
func (s *Server) handleReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	locations, _ := s.Store.AllLocations(r.Context())
	locViews := []map[string]any{}
	for _, l := range locations {
		locViews = append(locViews, locationResponse(l))
	}
	types, _ := s.Store.AllSampleTypes(r.Context())
	typeViews := []map[string]any{}
	for _, st := range types {
		typeViews = append(typeViews, sampleTypeResponse(st))
	}
	snap, _ := s.Snap.Get(r.Context())
	snapView := map[string]any{}
	if snap != nil {
		regions := []map[string]any{}
		for _, reg := range snap.Regions {
			regions = append(regions, map[string]any{
				"locationId": reg.LocationID.String(),
				"name":       reg.Name,
				"latitude":   reg.Latitude,
				"longitude":  reg.Longitude,
				"coverageKm": reg.CoverageKm,
			})
		}
		snapView = map[string]any{
			"version":                    snap.Version,
			"status":                     snap.Status,
			"computedAt":                 formatTime(snap.ComputedAt),
			"networkRevision":            snap.NetworkRevision,
			"regions":                    regions,
			"activeCollectionPointCount": snap.ActiveCollectionPointCount,
		}
	}
	pr := principalFrom(r)
	resp := map[string]any{
		"locations":       locViews,
		"sampleTypes":     typeViews,
		"serviceability":  snapView,
	}
	if pr != nil && pr.User != nil {
		resp["userId"] = pr.User.UserID.String()
		resp["username"] = pr.User.Username
		resp["roles"] = pr.User.Roles
		resp["activeRole"] = pr.Role
	} else {
		resp["userId"] = ""
		resp["username"] = ""
		resp["roles"] = []string{}
		resp["activeRole"] = ""
	}
	writeData(w, http.StatusOK, resp)
}

