// runReset connects to the datastores, drops application-owned state, and
// fully recreates every table, collection and index. It does not seed the
// admin user or default sample types (those happen on next start). It is safe
// to call repeatedly and must be called while the application is stopped.
func runReset(ctx context.Context) error {
	conns, err := db.Connect(ctx)
	if err != nil {
		return err
	}
	defer conns.PG.Close()
	defer conns.Mongo.Disconnect(ctx)
	return db.ResetSchema(ctx, conns.PG, conns.Mongo, conns.DbName)
}","old_str":"log.Printf("created initial administrator %s (id=%s)", u.Username, u.UserID)
